import React from 'react';
import { useForm, useFieldArray, FormProvider, SubmitHandler, FieldValues } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import {
  Box,
  Button,
  Paper,
  Typography,
  IconButton,
  Divider,
  TextField,
  Grid,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  FormControlLabel,
  Switch,
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';
import EntityFields from './EntityFields';
import EntityEndpoints from './EntityEndpoints';
import CrudOperations from './CrudOperations';

type ConfigFormValues = {
  projectName: string;
  projectDescription: string;
  projectArtifactoryId: string;
  basePackageName: string;
  apiContextPath: string;
  emailContact: string;
  externalClients: Array<{
    name: string;
    baseUrl: string;
    timeout: number;
    retryAttempts: number;
    retryDelay: number;
    request: {
      method: string;
      path: string;
      headers: Array<{
        name: string;
        value: string;
      }>;
      queryParams: Array<{
        name: string;
        value: string;
        required: boolean;
      }>;
      requestBody?: {
        type: string;
        schema: string;
      };
    };
    responses: Array<{
      status: number;
      description: string;
      responseBody?: {
        type: string;
        schema: string;
      };
    }>;
  }>;
  entities: Array<{
    name: string;
    tableName: string;
    fields: Array<{
      name: string;
      type: string;
      required: boolean;
      unique: boolean;
      validations: Array<{
        type: string;
        message: string;
        value?: string;
      }>;
    }>;
    crudOperations: {
      enabled: boolean;
    };
    endpoints: Array<{
      name: string;
      method: string;
      path: string;
      summary: string;
      description: string;
      returnType: string;
    }>;
  }>;
};

const validationSchema: yup.ObjectSchema<ConfigFormValues> = yup.object({
  projectName: yup.string().required('Project name is required'),
  projectDescription: yup.string().required('Project description is required'),
  projectArtifactoryId: yup.string().required('Project artifactory ID is required'),
  basePackageName: yup.string().required('Base package name is required'),
  apiContextPath: yup.string().required('API context path is required'),
  emailContact: yup.string().email('Invalid email').required('Email contact is required'),
  externalClients: yup.array().of(
    yup.object({
      name: yup.string().required('Client name is required'),
      baseUrl: yup.string().url('Invalid URL').required('Base URL is required'),
      timeout: yup.number().min(0).required('Timeout is required'),
      retryAttempts: yup.number().min(0).required('Retry attempts is required'),
      retryDelay: yup.number().min(0).required('Retry delay is required'),
      request: yup.object({
        method: yup.string().required('HTTP method is required'),
        path: yup.string().required('Path is required'),
        headers: yup.array().of(
          yup.object({
            name: yup.string().required('Header name is required'),
            value: yup.string().required('Header value is required'),
          })
        ).default([]),
        queryParams: yup.array().of(
          yup.object({
            name: yup.string().required('Parameter name is required'),
            value: yup.string().required('Parameter value is required'),
            required: yup.boolean().required(),
          })
        ).default([]),
        requestBody: yup.object({
          type: yup.string().required('Request body type is required'),
          schema: yup.string().required('Request body schema is required'),
        }).optional(),
      }).required(),
      responses: yup.array().of(
        yup.object({
          status: yup.number().required('Status code is required'),
          description: yup.string().required('Status description is required'),
          responseBody: yup.object({
            type: yup.string().required('Response body type is required'),
            schema: yup.string().required('Response body schema is required'),
          }).optional(),
        })
      ).required().min(1, 'At least one response status is required'),
    })
  ).default([]),
  entities: yup.array().of(
    yup.object({
      name: yup.string().required('Entity name is required'),
      tableName: yup.string().required('Table name is required'),
      fields: yup.array().of(
        yup.object({
          name: yup.string().required('Field name is required'),
          type: yup.string().required('Field type is required'),
          required: yup.boolean().required(),
          unique: yup.boolean().required(),
          validations: yup.array().of(
            yup.object({
              type: yup.string().required('Validation type is required'),
              message: yup.string().required('Validation message is required'),
              value: yup.string(),
            })
          ).required(),
        })
      ).required(),
      crudOperations: yup.object({
        enabled: yup.boolean().required(),
      }).required(),
      endpoints: yup.array().of(
        yup.object({
          name: yup.string().required('Endpoint name is required'),
          method: yup.string().required('HTTP method is required'),
          path: yup.string().required('Path is required'),
          summary: yup.string().required('Summary is required'),
          description: yup.string().required('Description is required'),
          returnType: yup.string().required('Return type is required'),
        })
      ).required(),
    })
  ).required(),
}).required();

const ConfigForm: React.FC = () => {
  const methods = useForm<ConfigFormValues>({
    resolver: yupResolver<ConfigFormValues>(validationSchema),
    defaultValues: {
      projectName: '',
      projectDescription: '',
      projectArtifactoryId: '',
      basePackageName: '',
      apiContextPath: '',
      emailContact: '',
      externalClients: [],
      entities: [],
    },
  });

  const { fields: entityFields, append: appendEntity, remove: removeEntity } = useFieldArray({
    control: methods.control,
    name: 'entities',
  });

  const { fields: clientFields, append: appendClient, remove: removeClient } = useFieldArray({
    control: methods.control,
    name: 'externalClients',
  });

  const onSubmit: SubmitHandler<ConfigFormValues> = (data) => {
    try {
      alert("test")
      // Convert the form data to the expected config.json format
      const config = {
        projectName: data.projectName,
        projectDescription: data.projectDescription,
        projectArtifactoryId: data.projectArtifactoryId,
        basePackageName: data.basePackageName,
        apiContextPath: data.apiContextPath,
        emailContact: data.emailContact,
        externalClients: data.externalClients.map(client => ({
          name: client.name,
          baseUrl: client.baseUrl,
          timeout: client.timeout,
          retryAttempts: client.retryAttempts,
          retryDelay: client.retryDelay,
          request: client.request,
          responses: client.responses,
        })),
        entities: data.entities.map(entity => ({
          name: entity.name,
          tableName: entity.tableName,
          fields: entity.fields.map(field => ({
            name: field.name,
            type: field.type,
            required: field.required,
            unique: field.unique,
            validations: field.validations.map(validation => ({
              type: validation.type,
              message: validation.message,
              ...(validation.value && { value: validation.value }),
            })),
          })),
          crudOperations: entity.crudOperations,
          endpoints: entity.endpoints,
        })),
      };

      // Create and download the config.json file
      const blob = new Blob([JSON.stringify(config, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'config.json';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);


      // var dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(config));
      // const a = document.getElementById('downloadAnchorElem');
      // // @ts-ignore
      // a.setAttribute("href", dataStr);
      // // @ts-ignore
      // a.setAttribute("download", "config.json");
      // // @ts-ignore
      // a.click();

    } catch (error) {
      console.error('Error generating config:', error);
      alert('Error generating config file. Please check the console for details.');
    }
  };

  return (
    <FormProvider {...methods}>
      <form onSubmit={methods.handleSubmit(onSubmit)}>
        <Paper sx={{ p: 3, mb: 3 }}>
          <Typography variant="h6" gutterBottom>
            Project Information
          </Typography>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            <TextField
              fullWidth
              label="Project Name"
              {...methods.register('projectName')}
              error={!!methods.formState.errors.projectName}
              helperText={methods.formState.errors.projectName?.message}
            />
            <TextField
              fullWidth
              multiline
              rows={3}
              label="Project Description"
              {...methods.register('projectDescription')}
              error={!!methods.formState.errors.projectDescription}
              helperText={methods.formState.errors.projectDescription?.message}
            />
            <TextField
              fullWidth
              label="Project Artifactory ID"
              {...methods.register('projectArtifactoryId')}
              error={!!methods.formState.errors.projectArtifactoryId}
              helperText={methods.formState.errors.projectArtifactoryId?.message}
            />
            <TextField
              fullWidth
              label="Base Package Name"
              {...methods.register('basePackageName')}
              error={!!methods.formState.errors.basePackageName}
              helperText={methods.formState.errors.basePackageName?.message}
            />
            <TextField
              fullWidth
              label="API Context Path"
              {...methods.register('apiContextPath')}
              error={!!methods.formState.errors.apiContextPath}
              helperText={methods.formState.errors.apiContextPath?.message}
            />
            <TextField
              fullWidth
              label="Email Contact"
              {...methods.register('emailContact')}
              error={!!methods.formState.errors.emailContact}
              helperText={methods.formState.errors.emailContact?.message}
            />
          </Box>
        </Paper>

        <Paper sx={{ p: 3, mb: 3 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
            <Typography variant="h6">External Clients</Typography>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={() => appendClient({
                name: '',
                baseUrl: '',
                timeout: 5000,
                retryAttempts: 3,
                retryDelay: 1000,
                request: {
                  method: 'GET',
                  path: '',
                  headers: [],
                  queryParams: [],
                },
                responses: [{
                  status: 200,
                  description: 'Success',
                }],
              })}
            >
              Add Client
            </Button>
          </Box>

          {clientFields.map((field, index) => (
            <Paper key={field.id} sx={{ p: 2, mb: 2 }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Typography variant="subtitle1">Client {index + 1}</Typography>
                <IconButton
                  color="error"
                  onClick={() => removeClient(index)}
                  size="small"
                >
                  <DeleteIcon />
                </IconButton>
              </Box>

              <Grid container spacing={2}>
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    label="Client Name"
                    {...methods.register(`externalClients.${index}.name`)}
                    error={!!methods.formState.errors.externalClients?.[index]?.name}
                    helperText={methods.formState.errors.externalClients?.[index]?.name?.message}
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    label="Base URL"
                    {...methods.register(`externalClients.${index}.baseUrl`)}
                    error={!!methods.formState.errors.externalClients?.[index]?.baseUrl}
                    helperText={methods.formState.errors.externalClients?.[index]?.baseUrl?.message}
                  />
                </Grid>
                <Grid item xs={12} sm={4}>
                  <TextField
                    fullWidth
                    type="number"
                    label="Timeout (ms)"
                    {...methods.register(`externalClients.${index}.timeout`, { valueAsNumber: true })}
                    error={!!methods.formState.errors.externalClients?.[index]?.timeout}
                    helperText={methods.formState.errors.externalClients?.[index]?.timeout?.message}
                  />
                </Grid>
                <Grid item xs={12} sm={4}>
                  <TextField
                    fullWidth
                    type="number"
                    label="Retry Attempts"
                    {...methods.register(`externalClients.${index}.retryAttempts`, { valueAsNumber: true })}
                    error={!!methods.formState.errors.externalClients?.[index]?.retryAttempts}
                    helperText={methods.formState.errors.externalClients?.[index]?.retryAttempts?.message}
                  />
                </Grid>
                <Grid item xs={12} sm={4}>
                  <TextField
                    fullWidth
                    type="number"
                    label="Retry Delay (ms)"
                    {...methods.register(`externalClients.${index}.retryDelay`, { valueAsNumber: true })}
                    error={!!methods.formState.errors.externalClients?.[index]?.retryDelay}
                    helperText={methods.formState.errors.externalClients?.[index]?.retryDelay?.message}
                  />
                </Grid>

                <Grid item xs={12}>
                  <Divider sx={{ my: 2 }} />
                  <Typography variant="subtitle2" gutterBottom>
                    Request Configuration
                  </Typography>
                </Grid>

                <Grid item xs={12} sm={6}>
                  <FormControl fullWidth>
                    <InputLabel>HTTP Method</InputLabel>
                    <Select
                      label="HTTP Method"
                      {...methods.register(`externalClients.${index}.request.method`)}
                      defaultValue="GET"
                    >
                      {['GET', 'POST', 'PUT', 'DELETE', 'PATCH'].map((method) => (
                        <MenuItem key={method} value={method}>
                          {method}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    fullWidth
                    label="Path"
                    {...methods.register(`externalClients.${index}.request.path`)}
                    error={!!methods.formState.errors.externalClients?.[index]?.request?.path}
                    helperText={methods.formState.errors.externalClients?.[index]?.request?.path?.message}
                  />
                </Grid>

                <Grid item xs={12}>
                  <Typography variant="subtitle2" gutterBottom>
                    Headers
                  </Typography>
                  <Box sx={{ mb: 2 }}>
                    {methods.watch(`externalClients.${index}.request.headers`)?.map((_, headerIndex) => (
                      <Box key={headerIndex} sx={{ display: 'flex', gap: 1, mb: 1 }}>
                        <TextField
                          size="small"
                          label="Name"
                          {...methods.register(`externalClients.${index}.request.headers.${headerIndex}.name`)}
                        />
                        <TextField
                          size="small"
                          label="Value"
                          {...methods.register(`externalClients.${index}.request.headers.${headerIndex}.value`)}
                        />
                        <IconButton
                          size="small"
                          onClick={() => {
                            const headers = methods.getValues(`externalClients.${index}.request.headers`);
                            headers.splice(headerIndex, 1);
                            methods.setValue(`externalClients.${index}.request.headers`, headers);
                          }}
                        >
                          <DeleteIcon />
                        </IconButton>
                      </Box>
                    ))}
                    <Button
                      size="small"
                      startIcon={<AddIcon />}
                      onClick={() => {
                        const headers = methods.getValues(`externalClients.${index}.request.headers`) || [];
                        headers.push({ name: '', value: '' });
                        methods.setValue(`externalClients.${index}.request.headers`, headers);
                      }}
                    >
                      Add Header
                    </Button>
                  </Box>
                </Grid>

                <Grid item xs={12}>
                  <Typography variant="subtitle2" gutterBottom>
                    Query Parameters
                  </Typography>
                  <Box sx={{ mb: 2 }}>
                    {methods.watch(`externalClients.${index}.request.queryParams`)?.map((_, paramIndex) => (
                      <Box key={paramIndex} sx={{ display: 'flex', gap: 1, mb: 1, alignItems: 'center' }}>
                        <TextField
                          size="small"
                          label="Name"
                          {...methods.register(`externalClients.${index}.request.queryParams.${paramIndex}.name`)}
                        />
                        <TextField
                          size="small"
                          label="Value"
                          {...methods.register(`externalClients.${index}.request.queryParams.${paramIndex}.value`)}
                        />
                        <FormControlLabel
                          control={
                            <Switch
                              size="small"
                              {...methods.register(`externalClients.${index}.request.queryParams.${paramIndex}.required`)}
                            />
                          }
                          label="Required"
                        />
                        <IconButton
                          size="small"
                          onClick={() => {
                            const params = methods.getValues(`externalClients.${index}.request.queryParams`);
                            params.splice(paramIndex, 1);
                            methods.setValue(`externalClients.${index}.request.queryParams`, params);
                          }}
                        >
                          <DeleteIcon />
                        </IconButton>
                      </Box>
                    ))}
                    <Button
                      size="small"
                      startIcon={<AddIcon />}
                      onClick={() => {
                        const params = methods.getValues(`externalClients.${index}.request.queryParams`) || [];
                        params.push({ name: '', value: '', required: false });
                        methods.setValue(`externalClients.${index}.request.queryParams`, params);
                      }}
                    >
                      Add Query Parameter
                    </Button>
                  </Box>
                </Grid>

                <Grid item xs={12}>
                  <Typography variant="subtitle2" gutterBottom>
                    Request Body (Optional)
                  </Typography>
                  <Grid container spacing={2}>
                    <Grid item xs={12} sm={6}>
                      <TextField
                        fullWidth
                        label="Type"
                        {...methods.register(`externalClients.${index}.request.requestBody.type`)}
                      />
                    </Grid>
                    <Grid item xs={12}>
                      <TextField
                        fullWidth
                        multiline
                        rows={4}
                        label="Schema (JSON)"
                        {...methods.register(`externalClients.${index}.request.requestBody.schema`)}
                      />
                    </Grid>
                  </Grid>
                </Grid>

                <Grid item xs={12}>
                  <Divider sx={{ my: 2 }} />
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                    <Typography variant="subtitle2">Response Statuses</Typography>
                    <Button
                      size="small"
                      startIcon={<AddIcon />}
                      onClick={() => {
                        const responses = methods.getValues(`externalClients.${index}.responses`) || [];
                        responses.push({ status: 200, description: 'Success' });
                        methods.setValue(`externalClients.${index}.responses`, responses);
                      }}
                    >
                      Add Response
                    </Button>
                  </Box>
                  {methods.watch(`externalClients.${index}.responses`)?.map((_, responseIndex) => (
                    <Paper key={responseIndex} sx={{ p: 2, mb: 2 }}>
                      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                        <Typography variant="subtitle2">Response {responseIndex + 1}</Typography>
                        <IconButton
                          size="small"
                          onClick={() => {
                            const responses = methods.getValues(`externalClients.${index}.responses`);
                            if (responses.length > 1) {
                              responses.splice(responseIndex, 1);
                              methods.setValue(`externalClients.${index}.responses`, responses);
                            }
                          }}
                          disabled={methods.watch(`externalClients.${index}.responses`)?.length === 1}
                        >
                          <DeleteIcon />
                        </IconButton>
                      </Box>
                      <Grid container spacing={2}>
                        <Grid item xs={12} sm={6}>
                          <TextField
                            fullWidth
                            type="number"
                            label="Status Code"
                            {...methods.register(`externalClients.${index}.responses.${responseIndex}.status`, { valueAsNumber: true })}
                            error={!!methods.formState.errors.externalClients?.[index]?.responses?.[responseIndex]?.status}
                            helperText={methods.formState.errors.externalClients?.[index]?.responses?.[responseIndex]?.status?.message}
                          />
                        </Grid>
                        <Grid item xs={12} sm={6}>
                          <TextField
                            fullWidth
                            label="Description"
                            {...methods.register(`externalClients.${index}.responses.${responseIndex}.description`)}
                            error={!!methods.formState.errors.externalClients?.[index]?.responses?.[responseIndex]?.description}
                            helperText={methods.formState.errors.externalClients?.[index]?.responses?.[responseIndex]?.description?.message}
                          />
                        </Grid>
                        <Grid item xs={12}>
                          <Typography variant="subtitle2" gutterBottom>
                            Response Body (Optional)
                          </Typography>
                          <Grid container spacing={2}>
                            <Grid item xs={12} sm={6}>
                              <TextField
                                fullWidth
                                label="Type"
                                {...methods.register(`externalClients.${index}.responses.${responseIndex}.responseBody.type`)}
                              />
                            </Grid>
                            <Grid item xs={12}>
                              <TextField
                                fullWidth
                                multiline
                                rows={4}
                                label="Schema (JSON)"
                                {...methods.register(`externalClients.${index}.responses.${responseIndex}.responseBody.schema`)}
                              />
                            </Grid>
                          </Grid>
                        </Grid>
                      </Grid>
                    </Paper>
                  ))}
                </Grid>
              </Grid>
            </Paper>
          ))}
        </Paper>

        <Paper sx={{ p: 3, mb: 3 }}>
          <Box sx={{ mb: 3 }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
              <Typography variant="h6">Entities</Typography>
              <Button
                variant="contained"
                startIcon={<AddIcon />}
                onClick={() => appendEntity({
                  name: '',
                  tableName: '',
                  fields: [],
                  crudOperations: { enabled: false },
                  endpoints: [],
                })}
              >
                Add Entity
              </Button>
            </Box>

            {entityFields.map((field, index) => (
              <Paper key={field.id} sx={{ p: 3, mb: 2 }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                  <Typography variant="h6">Entity {index + 1}</Typography>
                  <IconButton
                    color="error"
                    onClick={() => removeEntity(index)}
                    disabled={entityFields.length === 1}
                  >
                    <DeleteIcon />
                  </IconButton>
                </Box>

                <Box sx={{ display: 'flex', gap: 2, mb: 3 }}>
                  <TextField
                    fullWidth
                    label="Entity Name"
                    {...methods.register(`entities.${index}.name`)}
                    error={!!methods.formState.errors.entities?.[index]?.name}
                    helperText={methods.formState.errors.entities?.[index]?.name?.message}
                  />
                  <TextField
                    fullWidth
                    label="Table Name"
                    {...methods.register(`entities.${index}.tableName`)}
                    error={!!methods.formState.errors.entities?.[index]?.tableName}
                    helperText={methods.formState.errors.entities?.[index]?.tableName?.message}
                  />
                </Box>

                <Divider sx={{ my: 3 }} />

                <Typography variant="subtitle1" gutterBottom>
                  Fields
                </Typography>
                <EntityFields control={methods.control} entityIndex={index} />

                <Divider sx={{ my: 3 }} />

                <Typography variant="subtitle1" gutterBottom>
                  CRUD Operations
                </Typography>
                <CrudOperations control={methods.control} entityIndex={index} />

                <Divider sx={{ my: 3 }} />

                <Typography variant="subtitle1" gutterBottom>
                  Custom Endpoints
                </Typography>
                <EntityEndpoints control={methods.control} entityIndex={index} />
              </Paper>
            ))}
          </Box>
        </Paper>

        <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
          <Button
            type="submit"
            variant="contained"
            color="primary"
            size="large"
            disabled={methods.formState.isSubmitting}
          >
            {methods.formState.isSubmitting ? 'Generating...' : 'Generate Config'}
          </Button>
        </Box>
      </form>
    </FormProvider>
  );
};

export default ConfigForm;
