import React from 'react';
import { useFieldArray, Control } from 'react-hook-form';
import {
  Box,
  Grid,
  TextField,
  IconButton,
  Typography,
  Button,
  Paper,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
} from '@mui/material';
import { Add as AddIcon, Delete as DeleteIcon } from '@mui/icons-material';

interface EntityEndpointsProps {
  control: Control<any>;
  entityIndex: number;
}

const HTTP_METHODS = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'];

const RETURN_TYPES = [
  'ResponseEntity<Void>',
  'ResponseEntity<String>',
  'ResponseEntity<Map<String, Object>>',
  'ResponseEntity<List<Object>>',
  'ResponseEntity<Page<Object>>',
];

export default function EntityEndpoints({ control, entityIndex }: EntityEndpointsProps) {
  const { fields, append, remove } = useFieldArray({
    control,
    name: `entities.${entityIndex}.endpoints`,
  });

  return (
    <Box>
      {fields.map((endpoint, endpointIndex) => (
        <Paper key={endpoint.id} sx={{ p: 2, mb: 2 }}>
          <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
            <Typography variant="subtitle1">Endpoint {endpointIndex + 1}</Typography>
            <IconButton onClick={() => remove(endpointIndex)} color="error" size="small">
              <DeleteIcon />
            </IconButton>
          </Box>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Name"
                {...control.register(`entities.${entityIndex}.endpoints.${endpointIndex}.name`)}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>HTTP Method</InputLabel>
                <Select
                  label="HTTP Method"
                  {...control.register(`entities.${entityIndex}.endpoints.${endpointIndex}.method`)}
                >
                  {HTTP_METHODS.map((method) => (
                    <MenuItem key={method} value={method}>
                      {method}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Path"
                {...control.register(`entities.${entityIndex}.endpoints.${endpointIndex}.path`)}
                helperText="Example: /search or /{id}/status"
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Summary"
                {...control.register(`entities.${entityIndex}.endpoints.${endpointIndex}.summary`)}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Description"
                multiline
                rows={2}
                {...control.register(`entities.${entityIndex}.endpoints.${endpointIndex}.description`)}
              />
            </Grid>
            <Grid item xs={12}>
              <FormControl fullWidth>
                <InputLabel>Return Type</InputLabel>
                <Select
                  label="Return Type"
                  {...control.register(`entities.${entityIndex}.endpoints.${endpointIndex}.returnType`)}
                >
                  {RETURN_TYPES.map((type) => (
                    <MenuItem key={type} value={type}>
                      {type}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
          </Grid>
        </Paper>
      ))}
      <Button
        startIcon={<AddIcon />}
        onClick={() => append({
          name: '',
          method: 'GET',
          path: '',
          summary: '',
          description: '',
          returnType: 'ResponseEntity<Void>',
        })}
        variant="outlined"
        size="small"
        sx={{ mt: 1 }}
      >
        Add Endpoint
      </Button>
    </Box>
  );
} 