import React from 'react';
import { Control } from 'react-hook-form';
import {
  Box,
  FormControlLabel,
  Switch,
  Typography,
  Paper,
  Grid,
} from '@mui/material';

interface CrudOperationsProps {
  control: Control<any>;
  entityIndex: number;
}

export default function CrudOperations({ control, entityIndex }: CrudOperationsProps) {
  return (
    <Paper sx={{ p: 2, mb: 2 }}>
      <Typography variant="subtitle1" gutterBottom>
        CRUD Operations
      </Typography>
      <Grid container spacing={2}>
        <Grid item xs={12}>
          <FormControlLabel
            control={
              <Switch
                {...control.register(`entities.${entityIndex}.crudOperations.enabled`)}
                defaultChecked
              />
            }
            label="Enable CRUD Operations"
          />
        </Grid>
        <Grid item xs={12}>
          <Typography variant="body2" color="text.secondary">
            When enabled, the following operations will be generated:
          </Typography>
          <Box component="ul" sx={{ pl: 2, mt: 1 }}>
            <li>GET / - Get all entities with pagination</li>
            <li>GET /{'{id}'} - Get entity by ID</li>
            <li>POST / - Create new entity</li>
            <li>PUT /{'{id}'} - Update entity by ID</li>
            <li>DELETE /{'{id}'} - Delete entity by ID</li>
          </Box>
        </Grid>
      </Grid>
    </Paper>
  );
} 