import React from 'react';
import { useFieldArray, Control } from 'react-hook-form';
import {
  Box,
  Grid,
  TextField,
  IconButton,
  Typography,
  FormControlLabel,
  Switch,
  Button,
  Paper,
} from '@mui/material';
import { Add as AddIcon, Delete as DeleteIcon } from '@mui/icons-material';

interface EntityFieldsProps {
  control: Control<any>;
  entityIndex: number;
}

const FIELD_TYPES = [
  'String',
  'Integer',
  'Long',
  'Double',
  'BigDecimal',
  'Boolean',
  'LocalDate',
  'LocalDateTime',
  'List',
  'Map',
];

const VALIDATION_TYPES = [
  'NotNull',
  'NotBlank',
  'Size',
  'Min',
  'Max',
  'Pattern',
  'Email',
  'Past',
  'PastOrPresent',
  'Future',
  'FutureOrPresent',
  'DecimalMin',
  'DecimalMax',
  'Digits',
];

export default function EntityFields({ control, entityIndex }: EntityFieldsProps) {
  const { fields, append, remove } = useFieldArray({
    control,
    name: `entities.${entityIndex}.fields`,
  });

  return (
    <Box>
      {fields.map((field, fieldIndex) => (
        <Paper key={field.id} sx={{ p: 2, mb: 2 }}>
          <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
            <Typography variant="subtitle1">Field {fieldIndex + 1}</Typography>
            <IconButton onClick={() => remove(fieldIndex)} color="error" size="small">
              <DeleteIcon />
            </IconButton>
          </Box>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                select
                label="Type"
                {...control.register(`entities.${entityIndex}.fields.${fieldIndex}.type`)}
                SelectProps={{ native: true }}
              >
                {FIELD_TYPES.map((type) => (
                  <option key={type} value={type}>
                    {type}
                  </option>
                ))}
              </TextField>
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Name"
                {...control.register(`entities.${entityIndex}.fields.${fieldIndex}.name`)}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Description"
                multiline
                rows={2}
                {...control.register(`entities.${entityIndex}.fields.${fieldIndex}.description`)}
              />
            </Grid>
            <Grid item xs={12}>
              <FormControlLabel
                control={
                  <Switch
                    {...control.register(`entities.${entityIndex}.fields.${fieldIndex}.required`)}
                  />
                }
                label="Required"
              />
            </Grid>
            <Grid item xs={12}>
              <Typography variant="subtitle2" gutterBottom>
                Validations
              </Typography>
              <ValidationFields
                control={control}
                entityIndex={entityIndex}
                fieldIndex={fieldIndex}
              />
            </Grid>
          </Grid>
        </Paper>
      ))}
      <Button
        startIcon={<AddIcon />}
        onClick={() => append({ type: 'String', name: '', required: false, validations: [] })}
        variant="outlined"
        size="small"
        sx={{ mt: 1 }}
      >
        Add Field
      </Button>
    </Box>
  );
}

function ValidationFields({ control, entityIndex, fieldIndex }: { control: Control<any>; entityIndex: number; fieldIndex: number }) {
  const { fields, append, remove } = useFieldArray({
    control,
    name: `entities.${entityIndex}.fields.${fieldIndex}.validations`,
  });

  return (
    <Box>
      {fields.map((validation, validationIndex) => (
        <Paper key={validation.id} sx={{ p: 1, mb: 1 }}>
          <Box display="flex" alignItems="center" gap={1}>
            <TextField
              select
              label="Type"
              size="small"
              {...control.register(`entities.${entityIndex}.fields.${fieldIndex}.validations.${validationIndex}.type`)}
              SelectProps={{ native: true }}
            >
              {VALIDATION_TYPES.map((type) => (
                <option key={type} value={type}>
                  {type}
                </option>
              ))}
            </TextField>
            <TextField
              label="Message"
              size="small"
              {...control.register(`entities.${entityIndex}.fields.${fieldIndex}.validations.${validationIndex}.message`)}
            />
            <IconButton onClick={() => remove(validationIndex)} color="error" size="small">
              <DeleteIcon />
            </IconButton>
          </Box>
        </Paper>
      ))}
      <Button
        startIcon={<AddIcon />}
        onClick={() => append({ type: 'NotNull', message: '' })}
        variant="outlined"
        size="small"
        sx={{ mt: 1 }}
      >
        Add Validation
      </Button>
    </Box>
  );
} 